pub(crate) fn resolved_params(op: ByteOp) -> Vec<ResolvedParam> {
    op.param_types()
        .iter()
        .zip(op.param_names())
        .enumerate()
        .map(|(index, (ty, name))| ResolvedParam {
            id: ValueId::intrinsic_parameter(op.id(), index),
            name: (*name).to_owned(),
