            assert_eq!(errors[0].code, "SPX-H006");
            assert_eq!(
                errors[0].message,
                if attack == 2 {
                    "generic function call has no resolved template"
                } else {
                    "generic function call has an inconsistent instance identity"
                }
            );
        }
    }
