        kind: SourceForKind,
        step: ExpressionId,
    },
    /// Only the authenticated Yield-arm tail runs; never re-enter the authored body.
    OwnedIteratorStep {
        next: ExpressionId,
        assignment: ExpressionId,
        step: ValueId,
        remainder: ValueId,
    },
