//! Closed, compile-time scanner for `string_format` literals.
//!
//! The retained HIR contains the decoded source literal, never these derived
//! pieces. Every consumer reparses it, so a cached recipe cannot become an
//! authority separate from the canonical source expression.

pub(crate) const NAME: &str = "string_format";
pub(crate) const ID: &str = "core.string.format.literal.v1";
pub(crate) const MAX_TEMPLATE_BYTES: usize = 65_536;
pub(crate) const MAX_FIELDS: usize = 32;

pub(crate) fn operation_id() -> &'static crate::hir::DeclarationId {
    static IDENTITY: std::sync::LazyLock<crate::hir::DeclarationId> =
        std::sync::LazyLock::new(|| {
            crate::hir::DeclarationId::compiler(crate::hir::CompilerDeclaration::LiteralFormat)
        });
    &IDENTITY
}

pub(crate) fn resolved_params(args: &[crate::hir::ResolvedExpr]) -> Vec<crate::hir::ResolvedParam> {
    args.iter()
        .enumerate()
        .map(|(index, arg)| crate::hir::ResolvedParam {
            id: crate::hir::ValueId::intrinsic_parameter(ID, index),
            name: format!("value{index}"),
            ownership: if arg.ty == crate::hir::ResolvedType::String {
                crate::hir::OwnershipMode::Own
            } else {
                crate::hir::OwnershipMode::Value
            },
            ty: arg.ty.clone(),
            span: arg.span,
        })
        .collect()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ScanError {
    TooLong,
    TooManyFields,
    InvalidBrace,
    Capacity,
}

impl ScanError {
    pub(crate) const fn message(self) -> &'static str {
        match self {
            Self::TooLong => "string_format literal exceeds 65536 decoded UTF-8 bytes",
            Self::TooManyFields => "string_format literal exceeds 32 fields",
            Self::InvalidBrace => "string_format literal permits only {}, {{, and }} braces",
            Self::Capacity => "string_format scanner exceeds its builder budget",
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum Piece {
    Literal(String),
    Field,
}

/// Parse the decoded AST literal. Braces are ASCII, so byte indexing never
/// splits a UTF-8 scalar. Adjacent text and escaped braces coalesce into one
/// literal piece, and field order is exactly source order.
pub(crate) fn scan(template: &str) -> Result<Vec<Piece>, ScanError> {
    if template.len() > MAX_TEMPLATE_BYTES {
        return Err(ScanError::TooLong);
    }
    let scratch_bound = template
        .len()
        .saturating_mul(2)
        .saturating_add((2 * MAX_FIELDS + 1) * std::mem::size_of::<Piece>());
    if !crate::bounded_output::reserve_active_required(scratch_bound) {
        return Err(ScanError::Capacity);
    }
    let mut pieces = Vec::new();
    let mut literal = String::new();
    let mut cursor = 0;
    let mut plain_start = 0;
    let bytes = template.as_bytes();
    let mut fields = 0;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'{' | b'}' => {
                literal.push_str(&template[plain_start..cursor]);
                let next = bytes.get(cursor + 1).copied();
                match (bytes[cursor], next) {
                    (b'{', Some(b'{')) => literal.push('{'),
                    (b'}', Some(b'}')) => literal.push('}'),
                    (b'{', Some(b'}')) => {
                        if fields == MAX_FIELDS {
                            return Err(ScanError::TooManyFields);
                        }
                        if !literal.is_empty() {
                            pieces.push(Piece::Literal(std::mem::take(&mut literal)));
                        }
                        pieces.push(Piece::Field);
                        fields += 1;
                    }
                    _ => return Err(ScanError::InvalidBrace),
                }
                cursor += 2;
                plain_start = cursor;
            }
            _ => cursor += 1,
        }
    }
    literal.push_str(&template[plain_start..]);
    if !literal.is_empty() || pieces.is_empty() {
        pieces.push(Piece::Literal(literal));
    }
    Ok(pieces)
}

pub(crate) fn field_count(pieces: &[Piece]) -> usize {
    pieces
        .iter()
        .filter(|piece| matches!(piece, Piece::Field))
        .count()
}

pub(crate) fn expression_uses(expression: &crate::hir::ResolvedExpr) -> bool {
    let mut pending = vec![expression];
    while let Some(next) = pending.pop() {
        if matches!(
            next.kind,
            crate::hir::ResolvedExprKind::LiteralFormat { .. }
        ) {
            return true;
        }
        crate::hir::push_resolved_expression_children_in_authored_order(next, &mut pending);
    }
    false
}

/// Ordinary concat renewals and direct formatter-owned Place operands move
/// their authenticated source generation. This is derived from typed HIR, not
/// from attached cleanup flags or a callee name on an ordinary Call node.
#[cfg(test)]
pub(crate) fn moving_string_operands(
    function: &crate::hir::ResolvedFunction,
) -> std::collections::BTreeSet<crate::hir::ExpressionId> {
    checked_moving_string_operands(function).expect("unlimited test inventory")
}

/// New transfer entries reserve their maximum tree-node backing on the held
/// compiler ledger before insertion. The legacy concat/format census remains
/// unchanged; this does not claim funding for its existing traversal scratch.
pub(crate) fn checked_moving_string_operands(
    function: &crate::hir::ResolvedFunction,
) -> Result<std::collections::BTreeSet<crate::hir::ExpressionId>, crate::diagnostic::Diagnostic> {
    use crate::hir::{OwnershipMode, ResolvedExprKind, ResolvedType};
    let mut operands = crate::string_ops::same_owner_concat_operands(function);
    let mut refused = false;
    crate::hir::function_value::walk(function, |expression| {
        if refused {
            return;
        }
        if let Some(argument) = crate::string_ops::take::operand(expression) {
            if !operands.contains(&argument.id) {
                let bytes =
                    crate::cleanup_plan::compiler_btree_node_upper::<crate::hir::ExpressionId, ()>(
                    );
                if bytes.is_none_or(|bytes| !crate::bounded_output::reserve_active_required(bytes))
                {
                    crate::bounded_output::refuse_active_required(usize::MAX);
                    refused = true;
                    return;
                }
                operands.insert(argument.id.clone());
            }
        }
        if let ResolvedExprKind::LiteralFormat { args, .. } = &expression.kind {
            operands.extend(
                args.iter()
                    .filter(|argument| {
                        argument.ty == ResolvedType::String
                            && argument.ownership == OwnershipMode::Own
                            && matches!(argument.kind, ResolvedExprKind::Place(_))
                    })
                    .map(|argument| argument.id.clone()),
            );
        }
    });
    if refused {
        // The active ledger owns the first capacity receipt. Do not allocate
        // another message while propagating its selected refusal.
        Err(crate::diagnostic::Diagnostic::io("SPX-H006", String::new()))
    } else {
        Ok(operands)
    }
}

pub(crate) fn accepts_ast_type(ty: &crate::ast::Type) -> bool {
    matches!(
        ty,
        crate::ast::Type::I64
            | crate::ast::Type::U8
            | crate::ast::Type::Usize
            | crate::ast::Type::Bool
            | crate::ast::Type::String
    )
}

pub(crate) fn accepts_hir_type(ty: &crate::hir::ResolvedType) -> bool {
