#[derive(Clone, Copy)]
enum Frame<'a> {
    Function(&'a ResolvedFunction, usize),
    Expression(
        &'a ResolvedFunction,
        crate::hir::lexical_exit::ChildCursor<'a>,
        bool,
        usize,
    ),
