        (I64_FROM_USIZE_ID, StringOp::I64FromUsize),
    ];
    for (key, op) in KEYS {
        paid::tick(work, paid::str_units(key, id))?;
        if *key == id {
            return Ok(Some(*op));
        }
    }
    Ok(None)
}

